import { useEffect } from "react";

function App() {
  useEffect(() => {
    console.log("Calling API...");

    fetch("http://localhost:5000/test")
      .then((res) => {
        console.log("Status:", res.status); // debug thêm
        return res.text();
      })
      .then((data) => {
        console.log("API response:", data);
      })
      .catch((err) => {
        console.log("Fetch error:", err.message); // rất quan trọng!
      });
  }, []);

  return (
    <div>
      <h1>Test Connection</h1>
      <p>Mở F12 → Console để xem kết quả</p>
    </div>
  );
}

export default App;
